// BRDF does not require a Direction toward the surface(y is negative).
// That would cause wasted paths and divergence.
// [Tokuyoshi, Eto. 2024] introduced Bounded VNDF Sampling that removes "Almost" the unnecessary sample for GGX NDF.

// This shader show Bounded VNDF Sampling realizes it by putting red for unwanted incident direction(y is negative).

//     Accumulation           
//   -->|Buffer A| -------> |Image| 
//   |                |
//   ------------------

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec4 accum = texture(iChannel0,uv);
    accum.xyz /= accum.a; // Average

    fragColor = vec4(accum.xyz,1.0);
}

