void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    SetSeed(ivec2(fragCoord),iFrame);

    vec2 uv = (fragCoord * 2.0 + rnd2() - iResolution.xy) /iResolution.y;
    vec2 texuv = fragCoord / iResolution.xy;

    ErrorColoring = int(iTime * 0.5) % 2 == 1;

    // Camera Ray 
    Ray ray;
    ray.origin = vec3(0,0,-4);
    ray.direction = normalize(vec3(uv,3));

    if(uv.x < 0.0) sampleID = 1;
    else sampleID = 3;
    vec3 col;
    col = Pathtrace(ray);



    // UI
    if(abs(uv.x) < 0.005){
        col = vec3(0.7);
    }

    if(title((uv - vec2(0.3,0.7)) * 0.7,t1)){
        col = vec3(1.0);
    }

    if(title((uv - vec2(-1.5,0.7)) * 0.7,t2)){
        col = vec3(1.0);
    }

    if(title((uv - vec2(-0.45,-0.6)) * 0.5,t3) && ErrorColoring){
        col = vec3(1.0);
    }

    // Prefreme Resolution Check
    bool resize = texelFetch(iChannel0,ivec2(0),0).x != iResolution.x;
    resize = resize || (bool(texelFetch(iChannel0,ivec2(0),0).z) != ErrorColoring);

    // Accumulation
    vec4 accumCol = texture(iChannel0,texuv);
    if(resize) accumCol = vec4(col,1.0);
    else accumCol += vec4(col,1.0);

    // Store last resolution
    if(ivec2(fragCoord)==ivec2(0)) {
        accumCol = vec4(iResolution.xy,float(ErrorColoring),0.0);
    }






    fragColor = accumCol;
}
